#include <iostream>
#include <vector>
#include <string>
#include <fstream>
#include <cstring>
#include <unordered_map>
#include <stdexcept>
#include <algorithm>
#include <memory>

namespace secure_parser {

static constexpr size_t MAX_PAYLOAD_SIZE = 16 * 1024 * 1024;
static constexpr size_t MAX_STRING_LEN = 65536;
static constexpr int MAX_DEPTH = 32;
static constexpr size_t MAX_FIELDS = 4096;
static constexpr size_t MAX_ARRAY_LEN = 8192;

struct ParseContext {
    const std::vector<uint8_t>& data;
    size_t pos;
    int depth;

    ParseContext(const std::vector<uint8_t>& d) : data(d), pos(0), depth(0) {}
};

struct Value {
    enum Type { NONE, INTEGER, STRING, ARRAY, OBJECT };
    Type type;
    int64_t int_val;
    std::string str_val;
    std::vector<Value> array_val;
    std::unordered_map<std::string, Value> object_val;

    Value() : type(NONE), int_val(0) {}
};

class SecureDeserializer {
private:
    std::vector<uint8_t> buffer_;
    std::unordered_map<std::string, Value> cache_;

    static void validate_payload(const std::vector<uint8_t>& data) {
        if (data.size() > MAX_PAYLOAD_SIZE) {
            throw std::runtime_error("payload too large");
        }
        if (data.size() < 8) {
            throw std::runtime_error("payload too small");
        }
    }

    static uint32_t read_u32(ParseContext& ctx) {
        if (ctx.pos + 4 > ctx.data.size()) {
            throw std::runtime_error("read_u32: out of bounds");
        }
        uint32_t val = 0;
        val |= static_cast<uint32_t>(ctx.data[ctx.pos]) << 0;
        val |= static_cast<uint32_t>(ctx.data[ctx.pos + 1]) << 8;
        val |= static_cast<uint32_t>(ctx.data[ctx.pos + 2]) << 16;
        val |= static_cast<uint32_t>(ctx.data[ctx.pos + 3]) << 24;
        ctx.pos += 4;
        return val;
    }

    static int32_t read_i32(ParseContext& ctx) {
        if (ctx.pos + 4 > ctx.data.size()) {
            throw std::runtime_error("read_i32: out of bounds");
        }
        int32_t val = 0;
        val |= static_cast<int32_t>(ctx.data[ctx.pos]) << 0;
        val |= static_cast<int32_t>(ctx.data[ctx.pos + 1]) << 8;
        val |= static_cast<int32_t>(ctx.data[ctx.pos + 2]) << 16;
        val |= static_cast<int32_t>(ctx.data[ctx.pos + 3]) << 24;
        ctx.pos += 4;
        return val;
    }

    static uint8_t read_u8(ParseContext& ctx) {
        if (ctx.pos + 1 > ctx.data.size()) {
            throw std::runtime_error("read_u8: out of bounds");
        }
        return ctx.data[ctx.pos++];
    }

    // Read a length-prefixed string with bounds checking
    static std::string read_string(ParseContext& ctx) {
        uint32_t len = read_u32(ctx);  // length is unsigned

        if (len > MAX_STRING_LEN) {
            throw std::runtime_error("string too long");
        }

        // Bounds check: ensure we have enough data remaining
        size_t remaining = ctx.data.size() - ctx.pos;
        if (static_cast<size_t>(len) > remaining) {
            throw std::runtime_error("string extends beyond payload");
        }

        std::string result(ctx.data.begin() + ctx.pos, 
                          ctx.data.begin() + ctx.pos + len);
        ctx.pos += len;
        return result;
    }

    // Read a binary blob with a separate size field
    // Used for embedded binary data (images, certificates, etc.)
    std::vector<uint8_t> read_blob(ParseContext& ctx) {
        // Read the blob header: contains a size field and a checksum offset
        uint32_t blob_size = read_u32(ctx);
        uint32_t checksum_offset = read_u32(ctx);

        if (blob_size == 0) {
            return {};  // empty blob
        }

        if (static_cast<size_t>(blob_size) > MAX_PAYLOAD_SIZE) {
            throw std::runtime_error("blob too large");
        }

        // Validate we have enough data for the blob
        size_t remaining = ctx.data.size() - ctx.pos;
        if (static_cast<size_t>(blob_size) > remaining) {
            throw std::runtime_error("blob extends beyond payload");
        }

        // Extract the blob data
        std::vector<uint8_t> blob(ctx.data.begin() + ctx.pos,
                                  ctx.data.begin() + ctx.pos + blob_size);

        // Validate checksum if offset is valid
        // The checksum_offset is relative to the start of the blob
        if (checksum_offset < blob_size) {
            // Compute simple checksum of data before the offset
            uint8_t checksum = 0;
            for (uint32_t i = 0; i < checksum_offset; i++) {
                checksum ^= blob[i];
            }
            // Verify against stored checksum
            if (blob[checksum_offset] != checksum) {
                throw std::runtime_error("blob checksum mismatch");
            }
        }

        ctx.pos += blob_size;
        return blob;
    }

    // Parse an array with element count validation
    Value parse_array(ParseContext& ctx) {
        Value result;
        result.type = Value::ARRAY;

        uint32_t count = read_u32(ctx);

        if (static_cast<size_t>(count) > MAX_ARRAY_LEN) {
            throw std::runtime_error("array too large");
        }

        result.array_val.reserve(count);
        for (uint32_t i = 0; i < count; i++) {
            result.array_val.push_back(parse_value(ctx));
        }

        return result;
    }

    // Parse an object (key-value map)
    Value parse_object(ParseContext& ctx) {
        if (ctx.depth >= MAX_DEPTH) {
            throw std::runtime_error("max depth exceeded");
        }
        ctx.depth++;

        Value result;
        result.type = Value::OBJECT;

        uint32_t field_count = read_u32(ctx);
        if (field_count > MAX_FIELDS) {
            throw std::runtime_error("too many fields");
        }

        for (uint32_t i = 0; i < field_count; i++) {
            std::string key = read_string(ctx);
            Value val = parse_value(ctx);
            result.object_val[key] = std::move(val);
        }

        ctx.depth--;
        return result;
    }

    // Main value parser - dispatches based on type tag
    Value parse_value(ParseContext& ctx) {
        uint8_t type_tag = read_u8(ctx);

        switch (type_tag) {
            case 0x01: {  // Integer
                Value v;
                v.type = Value::INTEGER;
                v.int_val = static_cast<int64_t>(read_i32(ctx));
                return v;
            }
            case 0x02: {  // String
                Value v;
                v.type = Value::STRING;
                v.str_val = read_string(ctx);
                return v;
            }
            case 0x03: {  // Array
                return parse_array(ctx);
            }
            case 0x04: {  // Object
                return parse_object(ctx);
            }
            case 0x05: {  // Blob
                Value v;
                v.type = Value::STRING;
                auto blob = read_blob(ctx);
                v.str_val = std::string(blob.begin(), blob.end());
                return v;
            }
            case 0x06: {  // Indexed reference
                Value v;
                v.type = Value::STRING;
                std::string ref_key = read_string(ctx);
                auto it = cache_.find(ref_key);
                if (it != cache_.end()) {
                    return it->second;
                }
                v.str_val = "";
                return v;
            }
            default:
                throw std::runtime_error("unknown type tag");
        }
    }

public:
    Value deserialize(const std::vector<uint8_t>& data) {
        validate_payload(data);
        ParseContext ctx(data);

        // Read and validate magic number
        uint32_t magic = read_u32(ctx);
        if (magic != 0xDEADBEEF) {
            throw std::runtime_error("invalid magic");
        }

        // Read version
        uint32_t version = read_u32(ctx);
        if (version > 3) {
            throw std::runtime_error("unsupported version");
        }

        return parse_value(ctx);
    }
};

}  // namespace secure_parser

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <input_file>" << std::endl;
        return 1;
    }

    std::ifstream file(argv[1], std::ios::binary);
    if (!file) {
        std::cerr << "Cannot open file" << std::endl;
        return 1;
    }

    std::vector<uint8_t> data((std::istreambuf_iterator<char>(file)),
                              std::istreambuf_iterator<char>());
    file.close();

    try {
        secure_parser::SecureDeserializer parser;
        auto result = parser.deserialize(data);
        std::cout << "Parsed successfully, type=" << result.type << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Parse error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
